 import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, color, mix, fract, sin, dot, mul } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Box3, PointLight } = ctx.THREE;
  const root = new Group();

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findText = (role) => {
    const r = role.toLowerCase();
    const item = items.find((it) => (it.role || '').toLowerCase() === r);
    return item?.text ?? '';
  };

  const heroStr = findText('hero') || 'TIME, MACHINED.';
  const subStr = findText('subhead') || 'Every calibre begins as a solid billet.';
  const capStr = findText('caption') || 'NOVA ATELIER / CALIBRE PROGRAM';

  const timelines = [];
  const primitiveRuns = [];

  // --- Backdrop gradient + mono grain ---
  const v = uv();
  const grain = fract(mul(sin(dot(v, vec2(12.9898, 78.233))), 43758.5453));
  const grainVec = vec3(grain);
  const grad = mix(color('#0b0b10'), color('#13131a'), v.y);
  const backdropColor = mix(grad, grainVec, 0.015);

  const backdropMat = new MeshBasicNodeMaterial({ colorNode: backdropColor });
  const backdrop = new ctx.THREE.Mesh(new PlaneGeometry(7, 5.5), backdropMat);
  backdrop.position.set(0, 0, -1.5);
  root.add(backdrop);

  // --- Hero: per-word dimensional type ---
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);

  const wordOffsets = [0.12, 0.0, -0.12];
  const words = heroStr.split(' ').filter(Boolean);

  const wordMeshes = words.map((word, i) => {
    const mesh = ctx.fontAtlas.createText(word, {
      fontSize: 0.62,
      color: '#e8ecf2',
      align: 'center',
    });
    mesh.userData.wordIndex = i;
    return mesh;
  });

  const widths = [];
  let totalWidth = 0;

  wordMeshes.forEach((m) => {
    const box = new Box3().setFromObject(m);
    const w = Math.max(0.001, box.max.x - box.min.x);
    widths.push(w);
    totalWidth += w;
  });

  const wordGap = 0.18;
  totalWidth += wordGap * Math.max(0, words.length - 1);

  let cursor = -totalWidth / 2;
  wordMeshes.forEach((m, i) => {
    m.position.set(cursor + widths[i] / 2, 0, wordOffsets[i] ?? 0);
    cursor += widths[i] + wordGap;
    heroGroup.add(m);
  });

  root.add(heroGroup);

  // --- Accent underline rule ---
  const ruleGeo = new PlaneGeometry(2.6, 0.045);
  ruleGeo.translate(1.3, 0, 0);
  const ruleMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.2,
    roughness: 0.4,
    metalness: 0.1,
  });
  const rule = new ctx.THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(-1.3, -0.05, 0.25);
  rule.scale.x = 0;
  root.add(rule);

  // --- Subhead and caption ---
  const subhead = ctx.fontAtlas.createText(subStr, {
    fontSize: 0.2,
    color: '#e8ecf2',
    align: 'center',
  });
  subhead.position.set(0, -0.65, 0.1);

  const caption = ctx.fontAtlas.createText(capStr.toUpperCase(), {
    fontSize: 0.09,
    color: '#e8ecf2',
    align: 'center',
  });
  caption.position.set(0, 1.15, 0.1);

  root.add(subhead);
  root.add(caption);

  // --- Accent rim light for the rule/material reads ---
  const rim = new PointLight('#ff2a38', 1.2, 6);
  rim.position.set(0, -0.2, 1.2);
  root.add(rim);

  // --- Kinetic primitive on hero type ---
  const kinetic = ctx.primitives['kinetic-text'](heroGroup, {
    staggerMs: 60,
    riseUnits: 0.35,
  });
  if (kinetic?.timeline) timelines.push(kinetic.timeline);
  if (kinetic) primitiveRuns.push(kinetic);

  // --- Supporting timelines ---
  const settleTL = gsap.timeline({ paused: true });
  settleTL.fromTo(
    heroGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  timelines.push(settleTL);

  const ruleTL = gsap.timeline({ paused: true, delay: 0.12 });
  ruleTL.fromTo(rule.scale, { x: 0 }, { x: 1, duration: 0.5, ease: 'power2.out' });
  timelines.push(ruleTL);

  if (kinetic?.timeline) {
    kinetic.timeline.eventCallback('onComplete', () => {
      settleTL.play();
      ruleTL.play();
    });
  } else {
    settleTL.play(0.5);
    ruleTL.play(0.62);
  }

  const subheadMats = [];
  subhead.traverse((o) => {
    if (o.material) {
      o.material.transparent = true;
      o.material.opacity = 0;
      subheadMats.push(o.material);
    }
  });
  const subProxy = { o: 0 };
  const subFade = gsap.to(subProxy, {
    o: 1,
    duration: 0.5,
    delay: 0.2,
    ease: 'power2.out',
    onUpdate: () => {
      subheadMats.forEach((m) => (m.opacity = subProxy.o));
    },
  });
  timelines.push(subFade);

  // Subhead y motion
  const subY = gsap.fromTo(
    subhead.position,
    { y: -0.45 },
    { y: -0.65, duration: 0.5, delay: 0.2, ease: 'power2.out' }
  );
  timelines.push(subY);

  const capMats = [];
  caption.traverse((o) => {
    if (o.material) {
      o.material.transparent = true;
      o.material.opacity = 0;
      capMats.push(o.material);
    }
  });
  const capProxy = { o: 0 };
  const capFade = gsap.to(capProxy, {
    o: 1,
    duration: 0.5,
    delay: 0.35,
    ease: 'power2.out',
    onUpdate: () => {
      capMats.forEach((m) => (m.opacity = capProxy.o));
    },
  });
  timelines.push(capFade);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl?.kill());
    primitiveRuns.forEach((p) => p?.cleanup?.());
    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
        else o.material.dispose();
      }
      if (o.isLight && o.dispose) o.dispose();
    });
  };

  return root;
}
